# Nothingness budget: mean free path from pressure (Signature tool, labeled)
# lambda ~ kT/(sqrt(2) pi d^2 p), order of magnitude for air-like molecules
import math
def mfp(p_Pa):
    return 1.38e-23 * 293 / (1.414 * math.pi * (3.7e-10) ** 2 * p_Pa)
for name, p in [("LHC beam", 1e-8), ("sea level", 1e5)]:
    print("%-10s mean free path ~%.1e m" % (name, mfp(p)))
print("Budget (labeled): every beam/signal needs its computed nothingness")
